input, select { flex: 1; min-width: 0; padding: .65rem; font: inherit; border: 1px solid #9ba9b7; border-radius: 4px; }
.task-row { display: flex; align-items: center; gap: .75rem; margin: .6rem 0; padding: 1rem; background: white; border: 1px solid #d6dfe7; border-radius: 5px; }
